#!/usr/bin/env bash
# scripts/cuda/gen_ptx.sh — emit the Sofuu CUDA PTX module.
#
# PLAN-GPU-CUDA C0. Prefers nvcc when a CUDA toolkit happens to exist, but the
# canonical generator is clang's NVPTX backend (no toolkit, no CUDA headers):
#
#   clang++ -x cuda --cuda-device-only --cuda-gpu-arch=sm_70 ...
#
# The output is plain PTX text. The checked-in copy is generated by this script
# and gated by scripts/cuda/check_kernels.sh; the NVIDIA driver JITs sm_70 PTX
# on every newer architecture (T4 sm_75, Ampere, Hopper, Tegra).
#
# Usage: gen_ptx.sh [OUTPUT.ptx]
#        gen_ptx.sh --compiler     # print the selected compiler and exit

set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
SRC="$ROOT/src/cuda/kernels.cu"
ARCH="sm_70"

ENTRIES=(
    sofuu_gemv_q8_0
    sofuu_gemv_q4_k
    sofuu_gemv_q6_k
    sofuu_gemv_f32
    sofuu_rmsnorm
    sofuu_swiglu
    sofuu_rope_f32
    sofuu_kv_write_f32
    sofuu_attn_decode_f32
    sofuu_add_f32
)

find_clang() {
    local candidates=()
    [[ -n "${CXX:-}" ]] && candidates+=("$CXX")
    candidates+=(
        /opt/homebrew/opt/llvm/bin/clang++
        /usr/local/opt/llvm/bin/clang++
        /usr/lib/llvm-20/bin/clang++
        /usr/lib/llvm-19/bin/clang++
        /usr/lib/llvm-18/bin/clang++
        /usr/lib/llvm-17/bin/clang++
        clang++
    )
    for c in "${candidates[@]}"; do
        command -v "$c" >/dev/null 2>&1 || continue
        if "$c" --print-targets 2>/dev/null | grep -qi nvptx; then
            printf '%s\n' "$c"
            return 0
        fi
    done
    return 1
}

if [[ "${1:-}" == "--compiler" ]]; then
    if command -v nvcc >/dev/null 2>&1; then
        echo "nvcc"
    elif CLANG="$(find_clang)"; then
        echo "$CLANG (NVPTX)"
    else
        echo "none" >&2
        exit 1
    fi
    exit 0
fi

OUT="${1:-$ROOT/src/cuda/kernels.ptx}"
mkdir -p "$(dirname "$OUT")"

if command -v nvcc >/dev/null 2>&1; then
    echo "[cuda] generating PTX with nvcc (-arch=$ARCH)"
    nvcc -ptx "-arch=$ARCH" -O3 -o "$OUT" "$SRC"
else
    CLANG="$(find_clang)" || {
        echo "[cuda] ERROR: neither nvcc nor an NVPTX-capable clang++ was found." >&2
        echo "        Install a CUDA toolkit or LLVM built with the NVPTX target." >&2
        exit 1
    }
    echo "[cuda] generating PTX with $CLANG (NVPTX, $ARCH)"
    "$CLANG" -x cuda --cuda-device-only --cuda-gpu-arch="$ARCH" \
        -nocudainc -nocudalib -S -O3 -o "$OUT" "$SRC"
fi

missing=0
for k in "${ENTRIES[@]}"; do
    if ! grep -Eq "\.entry[[:space:]]+$k\(" "$OUT"; then
        echo "[cuda] ERROR: expected kernel entry '$k' is missing from $OUT" >&2
        missing=1
    fi
done
[[ "$missing" -eq 0 ]] || exit 1

# Deterministic gzip: no timestamp, no filename. Rust inflates this at runtime
# with flate2 (no zlib link dependency, which matters for musl builds).
gzip -9n -c "$OUT" > "$OUT.gz"

bytes=$(wc -c < "$OUT" | tr -d ' ')
gz=$(wc -c < "$OUT.gz" | tr -d ' ')
echo "[cuda] wrote $OUT ($bytes B), $OUT.gz ($gz B), ${#ENTRIES[@]} entries"
